  `judul` varchar(255) NOT NULL,
  `isi` longtext NOT NULL,
  `icon` varchar(255) DEFAULT NULL,
  `pdf_path` varchar(255) DEFAULT NULL,
  `pdf_size` bigint(20) DEFAULT NULL,
  `pdf_generated_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data untuk tabel `materi_buku_saku`
--

INSERT INTO `materi_buku_saku` (`id_materi`, `id_kategori`, `judul`, `isi`, `icon`, `pdf_path`, `pdf_size`, `pdf_generated_at`, `created_at`) VALUES
(1, 1, 'Pengertian Satpam', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pengertian Satpam</span></strong></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Satuan Pengamanan</strong>&nbsp;atau sering juga disingkat&nbsp;<strong>Satpam</strong>&nbsp;adalah satuan kelompok petugas yang dibentuk oleh instansi/proyek/badan usaha untuk melakukan keamanan fisik (physical security) dalam rangka penyelenggaraan keamanan swakarsa di lingkungan kerjanya.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kepolisian Negara&nbsp;Republik Indonesia&nbsp;menyadari bahwa&nbsp;polisi&nbsp;tidak mungkin bekerja sendiri dalam mengemban fungsi kepolisian. Oleh karena itu, lembaga satuan pengamanan secara resmi dibentuk pada&nbsp;30 Desember&nbsp;1980. (Wikipedia)</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-001.pdf', 74036, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(2, 1, 'Pancasila', '<h1 id=\"firstHeading\" class=\"firstHeading\" lang=\"id\" style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pancasila</span></h1>\n<div id=\"bodyContent\" class=\"mw-body-content\">\n<div id=\"mw-content-text\" class=\"mw-content-ltr\" dir=\"ltr\" lang=\"id\">\n<div class=\"mw-parser-output\">\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Pancasila</strong>&nbsp;adalah ideologi dasar bagi negara Indonesia. Nama ini terdiri dari dua kata dari&nbsp;Sanskerta:&nbsp;<em>pa&ntilde;ca</em>&nbsp;berarti lima dan&nbsp;<em>śīla</em>&nbsp;berarti prinsip atau asas. Pancasila merupakan rumusan dan pedoman kehidupan berbangsa dan bernegara bagi seluruh rakyat Indonesia.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Lima sendi utama penyusun Pancasila adalah Ketuhanan Yang Maha Esa, kemanusiaan yang adil dan beradab, persatuan Indonesia, kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan, dan keadilan sosial bagi seluruh rakyat Indonesia, dan tercantum pada paragraf ke-4 Preambule (Pembukaan)&nbsp;Undang-undang Dasar 1945.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Meskipun terjadi perubahan kandungan dan urutan lima sila Pancasila yang berlangsung dalam beberapa tahap selama masa&nbsp;perumusan Pancasila&nbsp;pada tahun 1945, tanggal 1 Juni diperingati sebagai hari lahirnya Pancasila.</span></p>\n<h2 style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><span id=\"Sejarah_perumusan_dan_lahirnya_Pancasila\" class=\"mw-headline\">Sejarah perumusan dan lahirnya Pancasila</span></span></h2>\n<div class=\"thumb tright\" style=\"text-align: justify;\">\n<div class=\"thumbinner\"><br />\n<div class=\"thumbcaption\">\n<div class=\"magnify\">&nbsp;</div>\n<span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Perisai Pancasila menampilkan lima lambang Pancasila.</span></div>\n</div>\n</div>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pada bulan 1 Maret 1945 dibentuk&nbsp;Badan Penyelidik Usaha Persiapan Kemerdekaan Indonesia&nbsp;yang diketuai oleh&nbsp;Dr. Kanjeng Raden Tumenggung (K.R.T.) Radjiman Wedyodiningrat. Dalam pidato pembukaannya dr. Radjiman antara lain mengajukan pertanyaan kepada anggota-anggota Sidang, \"Apa dasar Negara Indonesia yang akan kita bentuk ini?\"<sup id=\"cite_ref-Hatta_309_1-0\" class=\"reference\">[1]</sup></span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dalam upaya merumuskan Pancasila sebagai dasar negara yang resmi, terdapat usulan-usulan pribadi yang dikemukakan dalam Badan Penyelidik Usaha Persiapan Kemerdekaan Indonesia yaitu:</span></p>\n<ul style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><em>Lima Dasar</em>&nbsp;oleh&nbsp;Muhammad Yamin, yang berpidato pada tanggal&nbsp;29 Mei&nbsp;1945.&nbsp;Yamin&nbsp;merumuskan lima dasar sebagai berikut: Peri Kebangsaan, Peri Kemanusiaan, Peri Ketuhanan, Peri Kerakyatan, dan Kesejahteraan Rakyat. Dia menyatakan bahwa kelima sila yang dirumuskan itu berakar pada sejarah, peradaban, agama, dan hidup ketatanegaraan yang telah lama berkembang di&nbsp;Indonesia.&nbsp;Mohammad Hatta&nbsp;dalam memoarnya meragukan pidato Yamin tersebut.<sup id=\"cite_ref-Suwarno_p12_2-0\" class=\"reference\">[2]</sup></span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><em>Panca Sila</em>&nbsp;oleh&nbsp;Soekarno&nbsp;yang dikemukakan pada tanggal&nbsp;1 Juni&nbsp;1945&nbsp;dalam pidato spontannya yang kemudian dikenal dengan judul \"<em>Lahirnya Pancasila</em>\". Sukarno mengemukakan dasar-dasar sebagai berikut: Kebangsaan Indonesia; Internasionalisme atau Peri-Kemanusiaan; Mufakat atau Demokrasi, dasar perwakilan, dasar permusyawaratan; Kesejahteraan Sosial; Ketuhanan. Nama Pancasila itu diucapkan oleh Soekarno dalam pidatonya pada tanggal 1 Juni itu, katanya:</span></li>\n</ul>\n<dl>\n<dd>\n<dl>\n<dd><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><em>Sekarang banyaknya prinsip: kebangsaan, internasionalisme, mufakat, kesejahteraan, dan ketuhanan, lima bilangannya. Namanya bukan Panca Dharma, tetapi saya namakan ini dengan petunjuk seorang teman kita ahli bahasa - namanya ialah Pancasila. Sila artinya asas atau dasar, dan di atas kelima dasar itulah kita mendirikan negara Indonesia, kekal dan abadi.</em></span></dd>\n</dl>\n</dd>\n</dl>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sebelum sidang pertama itu berakhir, dibentuk suatu Panitia Kecil untuk:</span></p>\n<ul style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Merumuskan kembali Pancasila sebagai dasar Negara berdasarkan pidato yang diucapkan Soekarno pada tanggal 1 Juni 1945.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjadikan dokumen itu sebagai teks untuk memproklamasikan Indonesia Merdeka.</span></li>\n</ul>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dari Panitia Kecil itu dipilih 9 orang yang dikenal dengan&nbsp;Panitia Sembilan, untuk menyelenggarakan tugas itu. Rencana mereka itu disetujui pada tanggal&nbsp;22 Juni&nbsp;1945yang kemudian diberi nama&nbsp;Piagam Jakarta.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Setelah Rumusan Pancasila diterima sebagai dasar negara secara resmi beberapa dokumen penetapannya ialah:</span></p>\n<ul style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rumusan Pertama:&nbsp;Piagam Jakarta&nbsp;(<em>Jakarta Charter</em>) - tanggal&nbsp;22 Juni&nbsp;1945</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rumusan Kedua: Pembukaan Undang-undang Dasar 1945 - tanggal&nbsp;18 Agustus&nbsp;1945</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rumusan Ketiga: Mukaddimah Konstitusi Republik Indonesia Serikat - tanggal&nbsp;27 Desember&nbsp;1949</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rumusan Keempat: Mukaddimah Undang-undang Dasar Sementara - tanggal&nbsp;15 Agustus&nbsp;1950</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rumusan Kelima: Rumusan Pertama menjiwai Rumusan Kedua dan merupakan suatu rangkaian kesatuan dengan Konstitusi (merujuk&nbsp;Dekret Presiden 5 Juli 1959)</span></li>\n</ul>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Presiden&nbsp;Joko Widodo&nbsp;pada tanggal 1 Juni 2016 telah menandatangani Keputusan Presiden (Keppres) Nomor 24 Tahun 2016 tentang&nbsp;<strong>Hari Lahir Pancasila</strong>&nbsp;sekaligus menetapkannya sebagai hari libur nasional yang berlaku mulai tahun 2017.<sup id=\"cite_ref-3\" class=\"reference\"></sup></span></p>\n<h2 style=\"text-align: justify;\"><span id=\"Hari_Kesaktian_Pancasila\" class=\"mw-headline\" style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Hari Kesaktian Pancasila</span></h2>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pada tanggal&nbsp;30 September&nbsp;1965, terjadi insiden yang dinamakan&nbsp;Gerakan 30 September&nbsp;(G30S). Insiden ini sendiri masih menjadi perdebatan di tengah lingkungan akademisi mengenai siapa penggiatnya dan apa motif di belakangnya. Akan tetapi otoritas militer dan kelompok keagamaan terbesar saat itu menyebarkan kabar bahwa insiden tersebut merupakan usaha&nbsp;PKI&nbsp;mengubah unsur Pancasila menjadi ideologi komunis, untuk membubarkan&nbsp;Partai Komunis Indonesia, dan membenarkan peristiwa&nbsp;Pembantaian di Indonesia 1965&ndash;1966.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pada hari itu, enam Jenderal dan 1 Kapten serta berberapa orang lainnya dibunuh oleh oknum-oknum yang digambarkan pemerintah sebagai upaya kudeta. Gejolak yang timbul akibat G30S sendiri pada akhirnya berhasil diredam oleh otoritas militer Indonesia. Pemerintah Orde Baru kemudian menetapkan&nbsp;30 September&nbsp;sebagai Hari Peringatan Gerakan 30 September&nbsp;G30S&nbsp;dan tanggal&nbsp;1 Oktober&nbsp;ditetapkan sebagai&nbsp;<strong>Hari Kesaktian Pancasila</strong>.</span></p>\n<h2 style=\"text-align: justify;\"><span id=\"Butir-butir_pengamalan_Pancasila\" class=\"mw-headline\" style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Butir-butir pengamalan Pancasila</span></h2>\n<h3 style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><span id=\"Berdasarkan_Ketetapan_MPR_No.II.2FMPR.2F1978.5B4.5D\"></span><span id=\"Berdasarkan_Ketetapan_MPR_No.II/MPR/1978[4]\" class=\"mw-headline\">Berdasarkan Ketetapan MPR No.II/MPR/1978<sup id=\"cite_ref-4\" class=\"reference\"></sup></span></span></h3>\n<dl>\n<dt><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">1. Ketuhanan Yang Maha Esa</span></dt>\n</dl>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Percaya dan Takwa kepada Tuhan Yang Maha Esa sesuai dengan agama dan kepercayaan masing-masing menurut dasar kemanusiaan yang adil dan beradab.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Hormat menghormati dan bekerja sama antar pemeluk agama dan penganut-penganut kepercayaan yang berbeda-beda sehingga terbina kerukunan hidup.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Saling menghormati kebebasan menjalankan ibadah sesuai dengan agama dan kepercayaannya.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak memaksakan suatu agama dan kepercayaan kepada orang lain.</span></li>\n</ol>\n<dl>\n<dt><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">2. Kemanusiaan yang adil dan beradab</span></dt>\n</dl>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengakui persamaan derajat persamaan hak dan persamaan kewajiban antara sesama manusia.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Saling mencintai sesama manusia.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan sikap tenggang rasa.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak semena-mena terhadap orang lain.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjunjung tinggi nilai kemanusiaan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Gemar melakukan kegiatan kemanusiaan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Berani membela kebenaran dan keadilan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bangsa Indonesia merasa dirinya sebagai bagian dari seluruh umat manusia, karena itu dikembangkan sikap hormat-menghormati dan bekerja sama dengan bangsa lain.</span></li>\n</ol>\n<dl>\n<dt><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">3. Persatuan Indonesia</span></dt>\n</dl>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menempatkan kesatuan, persatuan, kepentingan, dan keselamatan bangsa dan negara di atas kepentingan pribadi atau golongan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rela berkorban untuk kepentingan bangsa dan negara.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Cinta Tanah Air dan Bangsa.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bangga sebagai Bangsa Indonesia dan ber-Tanah Air Indonesia.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memajukan pergaulan demi persatuan dan kesatuan bangsa yang ber-Bhinneka Tunggal Ika.</span></li>\n</ol>\n<dl>\n<dt><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">4. Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan dan perwakilan</span></dt>\n</dl>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengutamakan kepentingan negara dan masyarakat.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak memaksakan kehendak kepada orang lain.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengutamakan musyawarah dalam mengambil keputusan untuk kepentingan bersama.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Musyawarah untuk mencapai mufakat diliputi semangat kekeluargaan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dengan itikad baik dan rasa tanggung jawab menerima dan melaksanakan hasil musyawarah.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Musyawarah dilakukan dengan akal sehat dan sesuai dengan hati nurani yang luhur.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Keputusan yang diambil harus dapat dipertanggung jawabkan secara moral kepada Tuhan Yang Maha Esa, menjunjung tinggi harkat dan martabat manusia serta nilai-nilai kebenaran dan keadilan.</span></li>\n</ol>\n<dl>\n<dt><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">5. Keadilan sosial bagi seluruh rakyat Indonesia</span></dt>\n</dl>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan perbuatan-perbuatan yang luhur yang mencerminkan sikap dan suasana kekeluargaan dan gotong-royong.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bersikap adil.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjaga keseimbangan antara hak dan kewajiban.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menghormati hak-hak orang lain.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Suka memberi pertolongan kepada orang lain.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjauhi sikap pemerasan terhadap orang lain.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak bersifat boros.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak bergaya hidup mewah.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak melakukan perbuatan yang merugikan kepentingan umum.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Suka bekerja keras.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menghargai hasil karya orang lain.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bersama-sama berusaha mewujudkan kemajuan yang merata dan berkeadilan sosial.</span></li>\n</ol>\n<h3 style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><span id=\"Berdasarkan_ketetapan_MPR_no._I.2FMPR.2F2003\"></span><span id=\"Berdasarkan_ketetapan_MPR_no._I/MPR/2003\" class=\"mw-headline\">Berdasarkan ketetapan MPR no. I/MPR/2003</span></span></h3>\n<dl>\n<dt><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sila pertama</span></strong></dt>\n</dl>\n<div class=\"thumb tright\" style=\"text-align: justify;\">\n<div class=\"thumbinner\">\n<div class=\"thumbcaption\">\n<div class=\"magnify\">&nbsp;</div>\n<span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bintang</span></div>\n</div>\n</div>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bangsa Indonesia menyatakan kepercayaannya dan ketakwaannya terhadap Tuhan Yang Maha Esa.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Manusia Indonesia percaya dan takwa terhadap Tuhan Yang Maha Esa, sesuai dengan agama dan kepercayaannya masing-masing menurut dasar kemanusiaan yang adil dan beradab.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan sikap hormat menghormati dan bekerja sama antara pemeluk agama dengan penganut kepercayaan yang berbeda-beda terhadap Tuhan Yang Maha Esa.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Membina kerukunan hidup di antara sesama umat beragama dan kepercayaan terhadap Tuhan Yang Maha Esa.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Agama dan kepercayaan terhadap Tuhan Yang Maha Esa adalah masalah yang menyangkut hubungan pribadi manusia dengan Tuhan Yang Maha Esa.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan sikap saling menghormati kebebasan menjalankan ibadah sesuai dengan agama dan kepercayaannya masing-masing.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak memaksakan suatu agama dan kepercayaan terhadap Tuhan Yang Maha Esa kepada orang lain.</span></li>\n</ol>\n<dl>\n<dt><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sila kedua</span></strong></dt>\n</dl>\n<div class=\"thumb tright\" style=\"text-align: justify;\">\n<div class=\"thumbinner\">\n<div class=\"thumbcaption\">\n<div class=\"magnify\">&nbsp;</div>\n<span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rantai</span></div>\n</div>\n</div>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengakui dan memperlakukan manusia sesuai dengan harkat dan martabatnya sebagai makhluk Tuhan Yang Maha Esa.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengakui persamaan derajat, persamaan hak, dan kewajiban asasi setiap manusia, tanpa membeda-bedakan suku, keturunan, agama, kepercayaan, jenis kelamin, kedudukan sosial, warna kulit dan sebagainya.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan sikap saling mencintai sesama manusia.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan sikap saling tenggang rasa dan tepa selira.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan sikap tidak semena-mena terhadap orang lain.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjunjung tinggi nilai-nilai kemanusiaan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Gemar melakukan kegiatan kemanusiaan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Berani membela kebenaran dan keadilan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bangsa Indonesia merasa dirinya sebagai bagian dari seluruh umat manusia.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan sikap hormat menghormati dan bekerja sama dengan bangsa lain.</span></li>\n</ol>\n<dl>\n<dt><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sila ketiga</span></strong></dt>\n</dl>\n<div class=\"thumb tright\" style=\"text-align: justify;\">\n<div class=\"thumbinner\">\n<div class=\"thumbcaption\">\n<div class=\"magnify\">&nbsp;</div>\n<strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pohon Beringin</span></strong></div>\n</div>\n</div>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mampu menempatkan persatuan, kesatuan, serta kepentingan dan keselamatan bangsa dan negara sebagai kepentingan bersama di atas kepentingan pribadi dan golongan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sanggup dan rela berkorban untuk kepentingan negara dan bangsa apabila diperlukan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan rasa cinta kepada tanah air dan bangsa.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan rasa kebanggaan berkebangsaan dan bertanah air Indonesia.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memelihara ketertiban dunia yang berdasarkan kemerdekaan, perdamaian abadi, dan keadilan sosial.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan persatuan Indonesia atas dasar Bhinneka Tunggal Ika.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memajukan pergaulan demi persatuan dan kesatuan bangsa.</span></li>\n</ol>\n<dl>\n<dt><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sila keempat</span></strong></dt>\n</dl>\n<div class=\"thumb tright\" style=\"text-align: justify;\">\n<div class=\"thumbinner\">\n<div class=\"thumbcaption\">\n<div class=\"magnify\">&nbsp;</div>\n<strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kepala Banteng</span></strong></div>\n</div>\n</div>\n<ol style=\"text-align: justify;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sebagai warga negara dan warga masyarakat, setiap manusia Indonesia mempunyai kedudukan, hak, dan kewajiban yang sama.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak boleh memaksakan kehendak kepada orang lain.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengutamakan musyawarah dalam mengambil keputusan untuk kepentingan bersama.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Musyawarah untuk mencapai mufakat diliputi oleh semangat kekeluargaan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menghormati dan menjunjung tinggi setiap keputusan yang dicapai sebagai hasil musyawarah.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dengan iktikad baik dan rasa tanggung jawab menerima dan melaksanakan hasil keputusan musyawarah.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Di dalam musyawarah diutamakan kepentingan bersama di atas kepentingan pribadi dan golongan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Musyawarah dilakukan dengan akal sehat dan sesuai dengan hati nurani yang luhur.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Keputusan yang diambil harus dapat dipertanggungjawabkan secara moral kepada Tuhan Yang Maha Esa, menjunjung tinggi harkat dan martabat manusia, nilai-nilai kebenaran dan keadilan mengutamakan persatuan dan kesatuan demi kepentingan bersama.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memberikan kepercayaan kepada wakil-wakil yang dipercayai untuk melaksanakan pemusyawaratan.</span></li>\n</ol>\n<dl>\n<dt><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sila kelima</span></strong></dt>\n</dl>\n<div class=\"thumb tright\" style=\"text-align: justify;\">\n<div class=\"thumbinner\">\n<div class=\"thumbcaption\">\n<div class=\"magnify\">&nbsp;</div>\n<span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Padi dan Kapas</span></div>\n</div>\n</div>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan perbuatan yang luhur, yang mencerminkan sikap dan suasana kekeluargaan dan kegotongroyongan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengembangkan sikap adil terhadap sesama.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjaga keseimbangan antara hak dan kewajiban.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menghormati hak orang lain.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Suka memberi pertolongan kepada orang lain agar dapat berdiri sendiri.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak menggunakan hak milik untuk usaha-usaha yang bersifat pemerasan terhadap orang lain.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak menggunakan hak milik untuk hal-hal yang bersifat pemborosan dan gaya hidup mewah.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak menggunakan hak milik untuk bertentangan dengan atau merugikan kepentingan umum.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Suka bekerja keras.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Suka menghargai hasil karya orang lain yang bermanfaat bagi kemajuan dan kesejahteraan bersama.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Suka melakukan kegiatan dalam rangka mewujudkan kemajuan yang merata dan berkeadilan sosial.</span></li>\n</ol>\n</div>\n</div>\n</div>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-002.pdf', 87925, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(3, 1, 'Pembukaan UUD 1945', '<p style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Pembukaan UUD 1945</strong></span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">\"Bahwa sesungguhnya kemerdekaan itu ialah hak segala bangsa dan oleh sebab itu, maka penjajahan diatas dunia harus dihapuskan karena tidak sesuai dengan perikemanusiaan dan perikeadilan.\"</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">\"Dan perjuangan pergerakan kemerdekaan Indonesia telah sampailah kepada saat yang berbahagia dengan selamat sentosa mengantarkan rakyat Indonesia ke depan pintu gerbang kemerdekaan negara Indonesia, yang merdeka, bersatu, berdaulat, adil dan makmur.\"</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">\"Atas berkat rahmat Allah Yang Maha Kuasa dan dengan didorongkan oleh keinginan luhur, supaya berkehidupan kebangsaan yang bebas, maka rakyat Indonesia menyatakan dengan ini kemerdekaannya.\"</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">\"Kemudian daripada itu untuk membentuk suatu pemerintah negara Indonesia yang melindungi segenap bangsa Indonesia dan seluruh tumpah darah Indonesia dan untuk memajukan kesejahteraan umum, mencerdaskan kehidupan bangsa, dan ikut melaksanakan ketertiban dunia yang berdasarkan kemerdekaan, perdamaian abadi dan keadilan sosial, maka disusunlah kemerdekaan kebangsaan Indonesia itu dalam suatu Undang-Undang Dasar negara Indonesia, yang terbentuk dalam suatu susunan negara Republik Indonesia yang berkedaulatan rakyat dengan berdasar kepada :</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ketuhanan Yang Maha Esa,&nbsp;</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">kemanusiaan yang adil dan beradab,&nbsp;</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">persatuan Indonesia, dan kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan,&nbsp;</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">serta dengan mewujudkan suatu keadilan sosial bagi seluruh rakyat Indonesia.\"&nbsp;</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Renungan:</strong></span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-003.pdf', 74658, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(4, 1, 'Prinsip Prinsip Penuntun Satuan Pengamanan', '<h3 class=\"post-title entry-title\" style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Janji dan Prinsip - Prinsip Penuntun Tugas Satpam</span></h3>\n<div id=\"post-body-1274541798436534735\" class=\"post-body entry-content\" style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">ST.KAPOLRI NO. POLT/842/1988</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">TGL.20 - 12 - 1988</span></div>\n<div class=\"post-body entry-content\" style=\"text-align: justify;\"><br /><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><ins class=\"adsbygoogle\" data-ad-client=\"ca-pub-6158516659810787\" data-ad-format=\"auto\" data-ad-slot=\"7649392566\" data-adsbygoogle-status=\"done\"><ins id=\"aswift_2_expand\"><ins id=\"aswift_2_anchor\"></ins></ins></ins><strong>Prinsip-prinsip penuntun tugas satpam</strong></span></div>\n<ol style=\"text-align: justify;\">\n<li class=\"post-body entry-content\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kami anggota satuan pengamanan Memegang teguh disiplin patuh dan taat kepada pimpinan jujur dan bertanggung jawab</span></li>\n<li class=\"post-body entry-content\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kami anggota satuan pengamanan senantiasa menjaga kehormatan diri dan menghitung tinggi kehormatan satuan pengamanan</span></li>\n<li class=\"post-body entry-content\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kami anggota satuan pengamanan senantiasa waspada melaksanakan tugas sebagai pengaman dan penutup di lingkungan kerja</span></li>\n<li class=\"post-body entry-content\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kami anggota satuan pengamanan senantiasa bersikap Open dan tidak menganggap remeh sesuatu yang terjadi di lingkungan kerja</span></li>\n</ol>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kami anggota satuan pengamanan adalah tugas yang satu dan senantiasa bersikap etis dalam menegakkan peraturan</span><br /><br /><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><ins class=\"adsbygoogle\" data-ad-client=\"ca-pub-6158516659810787\" data-ad-format=\"auto\" data-ad-slot=\"7649392566\" data-adsbygoogle-status=\"done\"><ins id=\"aswift_3_expand\"><ins id=\"aswift_3_anchor\"></ins></ins></ins><strong>Janji Satpam</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Setia dan menjunjung tinggi Pancasila dan undang-undang Dasar 1945</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memegang teguh disiplin patuh dan taat kepada pimpinan serta berani bertanggung jawab terhadap setiap pelaksanaan tugas</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjaga kehormatan diri dan menjunjung tinggi kehormatan satuan pengamanan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjaga kesatuan dan persatuan satuan pengamanan serta aparat keamanan lainnya</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memelihara dan meningkatkan kewaspadaan serta kemampuan tugas demi tercapainya keamanan lingkungan</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-004.pdf', 74468, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(5, 1, 'Sejarah Terbentuknya Satpam', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sejarah Terbentuknya Satpam</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kepolisian Negara Republik Indonesia menyadari bahwa Polisi tidak mungkin bekerja sendiri dalam menciptakan masyarakat dan lingkungan yang aman dan tertib, hal inilah yang mendorong terbentuknya satpam di Indonesia. Kapolri (ketika itu dijabat Jenderal Polisi (Purn) Prof. DR. Awaloedin Djamin ) mengeluarkan Surat Keputusan Kapolri; No. SKEP/126/XII/1980 tertanggal 30 Desember 1980 Tentang Pola Pembinaan Satuan Pengamanan.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Selanjutnya, pada 30 Desember 1993, Polri mengukuhkan Jenderal Polisi (Purn) Prof. DR. Awaloedin Djamin menjadi Bapak Satpam dan menetapkan hari lahirnya Satpam Indonesia pada tanggal 30 Desember.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Seiring dengan berjalannya waktu, Satpam dituntut untuk lebih profesional baik dari segi struktur organisasi, perencanaan, tanggungjawab, prosedur, proses dan SDM nya, maka dikeluarkanlah Peraturan Kepala Kepolisian Negara Republik Indonesia No 24 Tahun 2007 Tanggal 10 Desember 2007 mengenai Sistem Manajemen Pengamanan Organisasi, Perusahaan dan/atau Instansi/Lembaga Pemerintah.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-005.pdf', 74406, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(6, 2, 'Tugas Pokok Satpam', '<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong><span style=\"font-size: 13pt;\">Tugas Pokok Satpam</span></strong></span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Maksud dari &ldquo;Tugas Pokok&rdquo; adalah :</span></p>\n<ul>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Suatu kewajiban yang harus dikerjakan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pekerjaan yang merupakan tanggungjawab</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Perintah untuk berbuat atau melakukan sesuatu demi mencapai suatu tujuan. </span></li>\n</ul>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jadi Tugas Pokok-nya Satpam adalah &ldquo;Menyelenggarakan keamanan dan ketertiban di lingkungan/tempat kerjanya yang meliputi aspek pengamanan fisik, personel, informasi dan pengamanan teknis lainnya&rdquo; (Perkapolri No 24 Tahun 2007, BAB III, Pasal 6, Ayat 1).</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menyelenggarakan mengandung arti :</span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengurus dan mengusahakan sesuatu (seperti memelihara, memiara, merawat).</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Melakukan atau melaksanakan (perintah, peraturan, rencana).</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menunaikan atau menyampaikan (maksud, tugas kewajiban).</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengurus dan memperhatikan (kepentingan, usaha, perkara).</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengadakan, mengatur, dan mengurus (pesta, pertunjukan, pameran, dsb).</span></li>\n</ol>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pengamanan Fisik adalah segala usaha dan kegiatan untuk mencegah / mengatasi timbulnya ancaman dan gangguan keamanan dan ketertiban lingkungan suatu instansi / proyek / badan usaha secara fisik melalui kegiatan pengaturan, penjagaan dan perondaan serta kegiatan lain yang disesuaikan dengan kebutuhan masing-masing instansi / proyek / badan usaha yang bersangkutan.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Objek yang diamankan-ditertibkan pada saat pengamanan fisik, adalah :</span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Asset : Benda bergerak &ndash; benda tidak bergerak, gedung, harta benda, dll.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Personil : Klien, Atasan, manajemen, Nasabah, Konsumen, Supplier, Pengunjung, Tamu, Rekan, dll.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Informasi : No Tlp pribadi staff, keberadaan staff, proses produksi, kekuatan pengamanan, data-data perusahaan, dll.</span></li>\n</ol>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kita telah belajar mengenai apa yang dimaksud dengan &ldquo;Aman&rdquo;, sekarang kita pelajari apa yang dimaksud dengan &ldquo;Tertib&rdquo;. Yang dimaksud dengan tertib adalah :</span></p>\n<ul>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Teratur, menurut aturan, rapi.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sopan, dengan sepatutnya.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Aturan, peraturan yang baik.</span></li>\n</ul>', 'icon1', 'uploads/buku_saku/materi_pdf/02-tugas-fungsi-peranan-dan-kegiatan/materi-006.pdf', 76374, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(7, 2, 'Fungsi Satpam', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Fungsi Satpam</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Apa yang dimaksud dengan Fungsi? Fungsi berarti :</span></p>\n<ul style=\"text-align: justify;\">\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Manfaat</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kegunaan</span></li>\n</ul>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jadi apa manfaat atau Kegunaan Satpam? Kegunaan atau Fungsi Satpam adalah &ldquo;Melindungi dan mengayomi lingkungan/tempat kerjanya dari setiap gangguan keamanan, serta menegakkan peraturan dan tata tertib yang berlaku di lingkungan kerjanya&rdquo;. (Perkapolri No 24 Tahun 2007, BAB III, Pasal 6, Ayat 2).</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Yang dimaksud dengan melindungi adalah : menjaga atau menyelamatkan supaya terhindar dari ancaman, gangguan dan marabahaya. Sedangkan yang dimaksud dengan mengayomi adalah memelihara atau memayungi.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Untuk lebih jelasnya, &ldquo;Melindungi adalah upaya fisik&rdquo; sedangkan &ldquo;Mengayomi&rdquo; adalah, seorang Satpam harus mampu memberikan rasa aman bagi orang-orang yang ada di sekitarnya.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Untuk bisa menegakan peraturan dan tata tertib, seorang Satpam harus memiliki Sikap dan Tampang Satpam yang baik.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/02-tugas-fungsi-peranan-dan-kegiatan/materi-007.pdf', 74785, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(8, 2, 'Peranan Satpam', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Peranan Satpam</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dalam pelaksanaan tugasnya sebagai pengemban fungsi kepolisian terbatas, Satpam berperan sebagai:</span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">unsur pembantu pimpinan organisasi, perusahaan dan/atau instansi/ lembaga pemerintah, pengguna Satpam di bidang pembinaan keamanan dan ketertiban lingkungan/tempat kerjanya;</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">unsur pembantu Polri dalam pembinaan keamanan dan ketertiban masyarakat, penegakan peraturan perundang-undangan serta menumbuhkan kesadaran dan kewaspadaan keamanan (security mindedness dan security awareness) di lingkungan/tempat kerjanya.( Perkapolri No 24 Tahun 2007, BAB III, Pasal 6, Ayat 2).</span></li>\n</ol>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Yang dimaksud dengan &ldquo;pembinaan&rdquo; adalah segala usaha, kegiatan dan pekerjaan untuk membimbing, mendorong, mengarahkan, menggerakan termasuk kegiatan koordinasi, untuk ikut serta secara aktif menciptakan, memelihara dan meningkatkan ketertiban dan keamanan bagi diri dan lingkungan kerjanya.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Untuk menegakan peraturan perundang-undangan serta menumbuhkan kesadaran dan kewaspadaan keamanan (security mindedness dan security awareness), seorang anggota Satpam pertama-tama harus tunduk dan tidak melanggar peraturan perundang-undangan (Termasuk peraturan Lalu lintas).</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Di dalam melaksanakan tugasnya, Satpam memiliki kewenangan untuk penegakan peraturan dan tata tertib karena Satpam merupakan pembantu pimpinan.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/02-tugas-fungsi-peranan-dan-kegiatan/materi-008.pdf', 74980, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(9, 3, 'Sikap dan Perilaku Seorang Satpam', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sikap dan Perilaku Seorang Satpam</span></strong></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Melayani Kepentingan Masyarakat dikawasan/lingkungan&nbsp; &nbsp; &nbsp; kerjanya</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Melindungi dan Menyelamatkan Jiwa, Raga, Harta benda dan kehormatan Personil dilingtkungan/kawasan kerjanya.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menghormati dan Menjunjung tinggi Hak Asasi Manusia</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mentaati Peraturan Negara dan Menghormati Norma-Norma yang berlaku dilingkungan kerja serta lingkungan&nbsp; &nbsp; &nbsp;Masyarakat</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dapat dijadikan suritauladan ditengah tengah Masyarakat Lingkungan kerjanya, terutama dalam mengemban Tugasnya</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ulet, Tabah, Sabar, Tawakal dan Percaya diri didalam mengemban Tugasnya</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Cepat Tanggap(responsif) dalam memberikan perlindungan/ pengamanan pada Masyarakat dilingkungan kerjanya</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memegang teguh rahasia jabatan yang dipercayakan padanya</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bertindak tegas,jujur,berani, adil, dan bijaksana</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">tidak menonjolkan kepentingan Pribadi dan mencampuri urusan orang lain yang tidak ada saut pautnya dengan tugas.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">bertindak secara wajar dan tidak berlebihan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memiliki rasa kebanggaan dan semangat KORSA (korps) serta senantiasanama baik ditengah - tengah masyarakat lingkungan kerjanya</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/03-pelaksanaan-tugas/materi-009.pdf', 74543, '2026-08-13 09:20:18', '2026-07-30 11:19:01');
INSERT INTO `materi_buku_saku` (`id_materi`, `id_kategori`, `judul`, `isi`, `icon`, `pdf_path`, `pdf_size`, `pdf_generated_at`, `created_at`) VALUES
(10, 3, 'Perlengkapan Perorangan', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Perlengkapan Perorangan</span></strong></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kartu Tanda Anggota (KTA)</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kartu Tanda Penduduk (KTP)</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Surat keterangan lainya (SIM)</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Buku catatan</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Buku saku</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">bolpoint/Pensil</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Peluit/ sempritan</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Perlengkapan lain sesuai tugasnya</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/03-pelaksanaan-tugas/materi-010.pdf', 73910, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(11, 3, 'Cara Menerima Tamu', '<p style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Cara Menerima Tamu</strong></span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Berpakaian rapi sesuai ketentuan yang berlaku dan berwibawa</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menyapa Tamu yang datang dengan ramahdan sopan, sambil berdiri dan menyalami Tamu</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mempersiloahkan tamu duduk dan mencatat identitas Tamu, menanyai keperluan Tamu dll</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Hindarkan sikap bahwa petugas lebih penting dari pada tamu</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memperlakukan sama atau tidak membedakan tamu, tapi perlu kita perhatikan usia, wanita hamil, anak-anak perlu diutamakan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">memberikan bantuan pengarahan dan petunjuk sesuai dengan kebutuhan Tamu sesuai SOP Perusahaan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menhindari sikap dan kata - kata yang kurang sopan/ simpatik</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Setelah selesai menyalami tamu, berterimakasih, dan mengantarkan tamu sampai pintu keluar.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/03-pelaksanaan-tugas/materi-011.pdf', 74254, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(12, 3, 'Cara Menerima Telephone', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Cara Menerima Telephone</span></strong></p>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">a. segera mengangkat saat telpon berdering,</span></p>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">b. memberikan salam sebut nama petugas dan nama Instansi/perusahaan</span></p>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">contoh:</span><br /><em><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">selamat pagi, siang, malam satpam TELKOM SALATIGA Dengan \"kusman\" dengan siapa saya bicara?</span></em></p>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">c. bersuara Jelas, berwibawa sehingga mudah didengar serta menghindari kata - kata yang kurang sopan</span></p>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">d. memberikan jawaban dengan baik, dan apabila tidak menguasai materi berikan penjelasan yang bijaksana</span></p>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">e. mencatat, pembicaraan telepon</span></p>\n<p><em><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">1. DENGAN SIAPA, 2. UNTUK SIAPA 3. ISI BERITA 4. KAPAN DITERIMA 5. SIAPA PENERIMA</span></em></p>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">f. kirim berita seperti saat menerima telepon</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">g. tutup telpon dengan ucapan terimakasih dan salam</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/03-pelaksanaan-tugas/materi-012.pdf', 74286, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(13, 3, 'Pengetahuan Dasar Yang Harus Dimiliki Oleh Anggota Satpam', '<p style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Pengetahuan Dasar Yang Harus Dimiliki Oleh Anggota Satpam</strong></span></p>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">a. mengetahui dan menguasai keadaan daerah kawasan kerja berdasarkan data atau Peta yang ada</span></p>\n<ol>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">untuk bangunan utama/ perkantoran</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">untuk gudang</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">untuk mesin pabrik</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">untuk instalasi listrik/ perangkat listrik</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">jalan, Lorong, gang didalam kawasan</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">nama, Alamat, serta nomor telepon pejabat dikawasan Kerjanya.</span></li>\n</ol>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">b. Mengetahui dan berusaha mengetahui sumber-sumber gangguan yang selalu menimbulkan kerawanan keamanan dan ketertiban dilingkungan/ kawasan kerjanya</span></p>\n<ol>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tempat bahan bakar</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mesin mesin Pabrik</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">instalasi Listrik</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">tempat parkir</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">pendingin ruangan (AC)</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">tempat kunci ruangan kantor dll.</span></li>\n</ol>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">c. kedua hal tersebut diatas harus dikuasai petugas patroli</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/03-pelaksanaan-tugas/materi-013.pdf', 74392, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(14, 1, 'Jenjang Pelatihan Satpam', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jenjang Pelatihan Satpam</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jenjang pelatihan satpam ada 3 tingkat yaitu :</span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Dasar (Gada Pratama)</strong>, merupakan pelatihan dasar wajib bagi calon anggota satpam. Lama pelatihan empat minggu dengan pola 232 jam pelajaran. Materi pelatihan a.l. Interpersonal Skill; Etika Profesi; Tugas Pokok, Fungsi dan Peranan Satpam, Kemampuan Kepolisian Terbatas; Bela Diri; Pengenalan Bahan Peledak; Barang Berharga dan Latihan Menembak; Pengetahuan Narkotika, Psikotropika dan Zat Adiktif Lainnya; Penggunaan Tongkat Polri dan Borgol; Pengetahuan Baris Berbaris dan Penghormatan;</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Penyelia (Gada Madya)</strong>, merupakan pelatihan lanjutan bagi anggota satpam yang telah memiliki kualifikasi Gada Pratama. Lama pelatihan dua minggu dengan pola 160 jam pelajaran dan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Manajer Keamanan (Gada Utama)</strong>, merupakan pelatihan yang boleh diikuti oleh siapa saja dalam level setingkat manajer, yaitu chief security officer atau manajer keamanan. Pola 100 jam pelajaran.</span></li>\n</ol>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Selain lembaga pendidikan kepolisian negara seperti Sekolah Polisi Negara, hanya perusahaan yang sudah memiliki izin operasional dari Kepala Polri sebagai badan usaha jasa pendidikan dan latihan keamanan, boleh menyelenggarakan pelatihan satpam. Kepolisian Wilayah, Kepolisian Wilayah Kota Besar, Kepolisian Resor, Kepolisian Resor Kota hanya melakukan latihan penyegaran.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-014.pdf', 74565, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(15, 1, 'Tugas Dan Fungsi Keamanan', '<p style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Tugas Dan Fungsi Keamanan</strong></span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kegiatan seorang petugas Keamanan terdiri dari { P6M }</span></strong></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">PENGATURAN.</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pengaturan disini dilihat dari medan yang diamankan, fungsi tambahan yang di keluarkan oleh perusahaan atau pimpinan keamanan. Dan dilihat dari kebutuhan perusahaan</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">PENJAGAAN</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Setiap keamanan memiliki fungsi dan tugas yang sama secara umum menjaga dan mengamankan semua asset, karyawan, atasan dan keamanan kerja dilingkungan kerja atau tempat-tempat tertentu sesuai dengan ploting yang diatur oleh perusahaan atau atasan. Dan dituntut seorang keamanan yang memiliki tanggung jawab, kedisiplinan, kejujuran tinggi.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">PENGAWALAN</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Melakukan pengawalan pada atasan atau asset perusahaan yang dibawa atau dipindahkan, atau diambil dari tempat lain yang diperlukan perusahaan atau yang dikeluarkan oleh perusahaan. Dan bertanggung jawab penuh terhadap keamanan dan kenyamanan selama dalam perjalanan sampai tujuan yang dimaksut.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">PATROLI</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tugas ini diwajibkan kepada setiap keamanan yang ditempatkan disetiap plot yang sudah diatur oleh atasan atau yang sudah ditunjuk oleh atasan keamanan guna melakukan kegiatan ini. Dan dapat melakukan pencegahan apabila dalam melakukan patroli mendapati hal-hal yang mencurigagan atau janggal dan melakukan pencekalan apabila terdapat hal-hal yang merupakan suatu pelanggaran didalam sistem pengamanan.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">PENYIDIKAN DAN PENYELIDIKAN</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kemampuan penyidikan dan penyelidikan setiap kejadian harus dimiliki oleh setiap personil sebelum ditangani oleh pihak yang berwajib, fungsi supaya dapat menggantisipasi sebelumnya untuk tidak terjadi hal-hal yang demikian</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">PELAPORAN</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Seorang keamanan harus dapat membuat laporan kepada atasan dan harus melaporkan segala sesuatu yang dianggap perlu untuk dilaporkan dan untuk diketahui oleh atasan atau pihak perusahaan. Dan dapat mengetahui kejadian tersebut penting atau tidaknya untuk dilaporkan atau dimutasikan.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">MENGAMANKAN</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Keamanan mempunyai hak untuk mengamankan pelaku dan mengamankan barang bukti atau mencari barang bukti serta dapat meminta saksi-saksi yang benar mengetahui kejadian dan wajib menjadi saksi apabila personil tersebut mengetahui kejadian tersebut.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-015.pdf', 75797, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(16, 1, 'SENYUM, SAPA, SALAM, TINDAK', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">SENYUM, SAPA, SALAM, TINDAK { S&sup3;T}</span></strong></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">SENYUM</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Biasakan senyum untuk menerima tamu, karena dengan senyum tamu akan merasa dihargai dan dihormati.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">SAPA</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sapalah tamu sebelum anda disapa, Tanya keperluannya dengan sopan, sampaikan hal tersebut kepada yang dituju oleh tamu, diperbolehkan masuk atau tidak, apabila diperbolehkan, arahkan tamu tersebut kepada yang bersangkutan. Dan apabila tidak lakukan penolakan secara baik-baik dengan alasan yang tidak menyinggung perasaan tamu. Hal tersebut diatas biasanya digunakan apabila yang bersangkutan bertugas dipos jaga kantor atau didalam kantor.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">SALAM</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ucapkan salam yang bersifat umum kepada tamu. Perlakukan tamu dengan sebaik-baiknya.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ucapan-ucapan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Selamat siang,. Apa ada yang bisa saya Bantu,. Trimakasih,. Maaf pak,. Silahkan pak / bu</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">TINDAK</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Apa bila ada tamu yang melanggar ketertiban didalam lingkungan perusahaan atau kantor terlebih dahulu dilakukan teguran secara baik-baik, dinasehati dan apabila yang bersangkutan masih melakukan dan tidak mengindahkan teguran tersebut amankan&hellip;&hellip;&hellip;.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-016.pdf', 74780, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(17, 1, 'PLOTING PERSONIL', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">PLOTING PERSONIL</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jumlah personil yang dimiliki oleh perusahaan yang nantinya akan ditempatkan atau di ploting harus disesuaikan. Penyesuaian tersebut harus dilakukan oleh atasan keamanan, dan atasan tersebut harus mengetahui lokasi &ndash; lokasi mana saja yang akan ditempatkan personil keamanan tersebut.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Untuk melihat berapa atau tempat mana saja yang harus ditempatkan personil dapat dilihat dari:</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">&Oslash; Kerawanan lokasi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">&Oslash; Penyesuaiyan jumlah personil yang dimiliki.</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">&Oslash; Asset yang terdapat dilokasi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">&Oslash; Luasnya lokasi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">&Oslash; Pos keluar masuk kendaraan dan tamu.</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">&Oslash; Kantor perusahaan</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kekuatan personil yang akan diplot oleh atasan keamanan dapat di pelajari dari beberapa aspek diatas, dengan demikian atasan keamanan dapat menentukan berapa personil yang diperlukan dilokasi ploting tersebut.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-017.pdf', 74768, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(18, 3, 'TINDAKAN PERTAMA TEMPAT KEJADIAN PERKARA { TPTKP }', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">TINDAKAN PERTAMA TEMPAT KEJADIAN PERKARA { TPTKP }</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Apabila ada perkara kejadian khususnya dilingkungan kerja</span></p>\n<ul>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Laporkan perkara tesebut kepada DANRU atau CHIEF</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pelajari TKP</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pelajari BOBOT, DAMPAK, EFEK dari perkara tersebut sebelum melaporkan kepada pihak yang berwajib { POLISI }</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Apabila perkara tersebut memang harus dilaporkan maka&hellip;&hellip;</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Laporan ke pihak kepolisian</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Amankan TKP / korban,/Pelaku</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jangan menyentuh barang apapun yang ada di TKP guna memudahkan penyelidikan pihak kepolisian, apabila olah TKP diperlukan untuk mengumpulkan bukti-bukti,hal ini dilakukan apabila perkata tersebut diatas merupakan tindak pencurian atau pembunuhan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jangan mengijinkan siapun kecuali Petugas masuk ke TKP</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Apabila pada saat kejadian keamanan berada ditempat kejadian, yang bersangkutan wajib untuk menjadi saksi atas kejadian tersebut</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Informasikan kepada petugas apa yang anda ketahui, mengenai TKP / korban, sebelum kejadian tersebut, untuk mempermudah pihak kepolisian menindak lanjuti atas perkara tersebut</span></li>\n</ul>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">INTROGASI KEJADIAN</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">untuk mengetahui dan menindak lanjuti perkara-perkara kejadian yang terjadi di lingkungan atau kejadian tersebut terjadi pada karyawan, maka harus di lakukan Introgasi saksi-saksi, pelaku, korban tersebut guna mendapatkan keterangan mengenai perkara tersebut.</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pertanyaan-pertanyaan inti&hellip;.SI ADI DE MEN BA TU</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Siapa&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;.?</span></strong><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ada dimana&hellip;&hellip;&hellip;&hellip;&hellip;.?</span></strong><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ada siapa&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;.?</span></strong><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dengan siapa, &hellip;..&hellip;&hellip;...?</span></strong><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menggunakan apa&hellip;&hellip;..?</span></strong><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengapa&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;..?</span></strong><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bagaimana&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;?</span></strong><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Waktu&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip;?</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Perluas kalimat-kalimat tersebut diatas guna mendapat keterangan yang diperlukan pada saat Introgasi.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/03-pelaksanaan-tugas/materi-018.pdf', 75841, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(19, 1, 'KOMANDAN REGU { DANRU }', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">KOMANDAN REGU { DANRU }</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Komandan regu harus memiliki pengalaman dan kemampuan yang lebih dari personil keamanan yang lain. Disamping itu harus memiliki kemampuan untuk membaca situasi dilingkungan kerja dan dapat menggambil keputusan apabila ada sesuatu hal</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tugas</span></strong></p>\n<ul>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menjadwal personil masing - masing regu.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengatur ploting personil.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menerima laporan [in put] dari personil.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Melanjutkan laporan [in put] ke chief security.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bertanggung jawab atas personil masing - masing.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Mengecek absent, buku mutasi, buku tamu, minimal 2 minggu sekali.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menampung arahan dan masukan dari personil</span></li>\n</ul>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Fungsi</span></p>\n<ul>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Danru adalah panjang tangan dari chief security, memiliki tugas yang berbeda dengan anggota lainnya.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">memiliki wewenang untuk mengatur dan menegur anggota</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Keamanan yang tidak taat pada peraturan perusahaan atau peraturan dari managemen keamanan itu sendiri.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Danru harus selalu siap apabila diperlukan oleh chief guna kepentingan angota dan perusahaan.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Danru memiliki hak untuk memindahkan personil di plot yang tadinya sudah ditentukan, sesudah mempelajari tindak kerawanan dititik tersebut.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memiliki jam kerja yang lebih dibanding anggotanya.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dituntut Royalitas kerja yang tinggi.</span></li>\n</ul>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-019.pdf', 74647, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(20, 1, 'PELANGGARAN – PELANGGARAN', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">PELANGGARAN &ndash; PELANGGARAN</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Adapun beberapa pelanggaran yang sering dilakukan oleh personil antara lain:</span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Datang tidak tepat waktu</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidur pada saat piket</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pulang tidak sesuai dengan waktu yang sudah ditentukan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak melakukan patroli di plot yang sudah ditentukan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak berada diplot seperti yang sudah ditentukan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak mengikuti peraturan perusahaan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak memeriksa kendaraan yang keluar masuk ( untuk yang piket di pos portal )</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tidak mengisi buku mutasi.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Izin tidak melapor.</span></li>\n</ol>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pelanggaran &ndash; pelanggaran tersebut diatas dapat dikenakan sanksi <strong>{ PERINGATAN }</strong> oleh pihak perusahaan, secara lisan <strong>{ TEGURAN }</strong> atau secara tulisan <strong>{ SURAT PERINGATAN }</strong></span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-020.pdf', 74983, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(21, 1, 'RAZIA', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">RAZIA</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Razia { Pemeriksaan } adalah pemeriksaan terhadap karyawan tanpa terkecuali yang bertujuan untuk menggantisipasi tindak pencurian atau pelanggaran lain yang kemunggkinan besar dilakukan oleh karyawan perusahaan itu sendiri.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Penindakan dapat dilakukan oleh pihak keamanan yang dibantu oleh pihak lain yang berkompeten dan dapat dimintai pertanggung jawaban atau pihak yang diminta oleh pihak keamanan untuk membantu dan demi lancarnya kegiatan itu sendiri.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Semua karyawan wajib diperiksa, sarana yang dibawa pada saat itu yang kemungkinan besar merupakan sarana untuk membawa barang atau asset yang dimiliki oleh perusahaan atau sajam sarana tersebut antara lain: Tas karyawan, Mobil karyawan dan dll wajib untuk diperiksa dengan teliti.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pemeriksaan atau Razia ini bukan mencurigai tapi mengantisipasi tindak pencurian atau pelanggaran yang akan merugikan perusahaan atau melanggara peraturan perusahaan itu sendiri. </span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Apabila ada karyawan melakukan tindakan pelanggaran lakukan tindakan:</span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Amankan barang bukti dari tindakan pelanggaran tersebut</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Minta data lengkap pelaku atau minta identitas pelaku secara lengkap</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Laporkan kepada atasan untuk tindak lanjut.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Lakukan pemanggilan untuk dimintai keterangan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Introgasi dan akan di muat kedalam berita acara</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Apabila pelanggaran itu merupakan tidak pencurian yang mengharuskan pelaku untuk dilaporkan kepada pihak yang berwajib maka laporkan dan disertai oleh berita acara tersebut.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-021.pdf', 74595, '2026-08-13 09:20:18', '2026-07-30 11:19:01'),
(22, 1, 'BERITA ACARA', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">BERITA ACARA</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Berita acara adalah laporan suatu kejadian, diambil dari keterangan-keterangan saksi atau pelaku atau korban.Berita acara harus dibuat dengan sedetail mungkin guna laporan kepada atasan dan harus sesuai dengan apa yang terjadi lapangan. Dan seorang keamanan harus bisa membuat berita acara tersebut dengan terlebih dahulu harus :</span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Melakukan pengecekan TKP</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memanggil Saksi &ndash; saksi</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memanggil Pelaku / Tersangka</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Memanggil Korban</span></li>\n</ol>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Dan fungsi berita acara tersebut selain untuk laporan kepada atasan juga berfungsi untuk laporan kepolisian apabila perkara tersebut dilanjutkan kepada pihak kepolisian.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-022.pdf', 74181, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(23, 1, 'OVER SHIFT', '<p style=\"text-align: center;\"><strong>OVER SHIFT</strong></p>\n<p style=\"text-align: justify;\"><br />OVER SHIFT adalah pergantian waktu atau jam tugas yang dilakukan setiap hari oleh setiap personil. yang harus di pelajari dalam hal ini adalah pada saat jam penggantian shift dimana shift yang lama harus menunggu sampai shift yang baru tiba dilokasi, dan dilakukan kordinasi sebelum pulang { minimal 20 menit }adapun kordinasi tersebut berfungsi untuk mengetahui segala sesuatu yang telah terjadi pada shieft lama, dan harus dilakukan serah terima ifentaris serta dilakukan pengecekan ifentaris oleh shift baru supaya tidak ada kesalahan dalam pendataan, dengan apa yang ada dilokasi ploting.</p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-023.pdf', 74060, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(24, 1, 'RADIO KOMUNIKASI { HT }', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">RADIO KOMUNIKASI { HT }</span></strong></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Radio komunikasi berfungsi untuk memberikan laporan kepada personil lain. Laporan-laporan tersebut dapat dilakukan untuk menginformasian situasi yang terjadi di ploting dimana personil tersebut di tempatkan,dan supaya diketahui oleh personil lain yang berposisi di plot masing-masing.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Apabila terjadi sesuatu dimana ploting personil berada, segera laporkan kepada personil yang lain menggunakan HT terseput supaya dapat diketahui dan apabila diperlukan bantuan , maka personil yang mengetahui wajib membantu personil yang memerlukan bantuan tersebut.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Selama dalam piket seorang keamanan yang memiliki fasilitas HT di larang keras mematikan sarana tersebut, guna mendapatkan laporan dari rekan-rekan sesama piket. Dan apabila di panggil oleh personil lain wajib menjawab apabila personil tersebut dapat menerima input dari personil yang memanggil.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Berkomunikasilah dengan bahasa yng sopan, tidak menggandung sara dan pornografi, dan dilarang keras menggunakan fasilitas tersebut untuk berkomunikasi dengan tujuan menghasut, mencaci, memarahi DLL yang tidak sesuai dengan etika berbicara atau etika agama.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/01-pengetahuan-dasar/materi-024.pdf', 74364, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(25, 4, 'ATRIBUT DAN SENJATA', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">ATRIBUT DAN SENJATA</span></strong></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">ATRIBUT</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Wajib bagi seorang keamanan memiliki seragam dan atribut lengkap sesuai dengan kebutuhan serta dituntut memiliki KTA, IJIN SAJAM dan BORGOL, yang dikeluarkan oleh polres atau polda setempat supaya legalitas tampilan keamanan berwibaya { Bukan Satpam Gadungan } dan dapat dipertanggung jawabkan.</span></p>\n<p><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">SAJAM</span></strong></p>\n<ul>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sangkur komando</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sangkur lempar</span></li>\n</ul>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">BORGOL</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Borgol yang digunakan oleh keamanan yaitu borgol setandar polri yaitu borgol lengan dan borgol ibu jari.</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Fungsi dari borgol tersebut adalah untuk mengamankan tersangka tindak perkara, sebelum dibawa kepada pihak yang berwajib, dapat juga sebagai alat pembela diri dengan tehnik-tehnik tertentu.</span><br /><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">SENPI</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sesuai dengan sifat, lingkup tugas dan ancaman terhadap lingkungan kerjanya, seperti bank, objek vital, kantor bendahara, anggota Satpam dapat dilengkapi dengan senjata api berdasarkan izin kepemilikan senjata api yang diberikan oleh kepala kepolisian negara.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jenis dan kaliber senjata yang dimaksud adalah</span></p>\n<ul>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Senjata api bahu, jenis senapan penabur dengan kaliber 12 GA</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Senjata api genggam, jenis pistol atau jenis revolver ; kaliber 0.32 inch; kaliber 0.25 inch; kaliber 0.22 inch</span></li>\n</ul>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Izin kepemilikan senjata api pada suatu instansi/proyek/badan usah dibatasi pada 1/3 kekuatan satuan pengamanan yang bertugas, tidak lebih dari 15 pucuk senjata api serta maksimal 3 magazen/silinder untuk setiap pucuk senjata api.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Referensi</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Peraturan Kepala Polri No. Pol. 18 Tahun 2006</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ketentuan perizinan senjata api ini diatur dalam Surat Keputusan Kapolri No Pol: Skep/244/II/1999 tertanggal 26 Februari 1999tentang Ketentuan Perizinan Senjata Api Non-Organik ABRI untuk Bela Diri.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/04-seragam-satuan-pengamanan/materi-025.pdf', 75754, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(26, 4, 'SARANA PENUNJANG', '<p style=\"text-align: center;\"><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">SARANA PENUNJANG</span></strong></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">IFENTARIS</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">IFENTARIS yang digunakan dan yang merupakan sarana penunjang keamanan harus di gunakan dan dijaga oleh setiap personil keamanan dengan sebaik-baiknya dan apabila hilang atau rusah bertanggung jawab sepenuhnya oleh yang melakukan atau semua keamanan, yang nantinya akan dimintai pertanggungjawaban oleh pihak perusahaan.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">BUKU TAMU</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Setiap tamu yang berkepentingan di areal perusahaan wajip lapor kepada personil keamanan dan wajib mengisi buku tamu guna mengidentifikasi apabila ada sesuatu hal yang tidak di inginkan. Dan bagi tamu karyawan yang menginap di dalam atau di MESS perusahan wajib lapor dan setiap tamu wajib meninggalkan identitas yang masih berlaku di pos piket.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">BUKU MUTASI</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Buku ini berfungsu untuk meninjau ulang segala kejadia yang terjadi dilokasi piket yang bersipat penting atau tidak, setiap personil piket wajib mengisi buku mutasi dengan jelas dan bertanggung jawab atas segala sesuatu yang dimuat di dalalm buku mutasi tersebut dan wajib membukukan apabila ada laporan dari personil yang patroli atau personil yang diplot di lokasi ploting yang sudah ditentukan yang wajib diisi oleh personil keamanan yang nantinya akan dimintai pertanggung jawaban atasan keamanan.</span></p>\n<p style=\"text-align: justify;\"><br /><strong><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">POS PORTAL</span></strong><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pos keamanan suatu intansi atau perusahaan berfungsi untuk pemeriksaan yang bersifat Global Atau menyeluruh, adapun yang diperikasa antara lain:</span></p>\n<ul>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">kendaraan tamu atau karyawan yang keluar masuk</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tamu yang keluar atau masuk</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Barang bawaan karyawan atau tamu yang keluar masuk</span></li>\n</ul>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pos keamanan berfungsi juga untuk menerima laporan dari personil yang diploting di plot masing-masing menggunakan sarana Radio Komunikasi atau secara langsung { LAPSIT } laporan situasi yang nantinya harus di bukukan kedalam buku mutasi. </span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Portal berfungsi untuk mengantisipasi kendaraan tamu atau karyawan yang menerobos karena tidak berkenan untuk melapor atau untuk diperiksa oleh personil keamanan.</span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Personil dipos memiliki hak penuh untuk memeriksa atau menghentikan kendaraan siapapun tanpa terkecuali guna pemeriksaan dan pencatatan untuk laporan harian personil piket itu sendiri.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/04-seragam-satuan-pengamanan/materi-026.pdf', 75795, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(27, 5, 'SOP – TRS 101 : Patroli Area', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>101</strong><strong>&nbsp;: Patroli Area</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Patroli dilaksanakan untuk memeriksa dan meyakinkan seluruh personil dan asset perusahaan serta area dalam keadaan aman&nbsp;tka&nbsp;dan memastikan bahwa ketertiban dapat dijaga.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Anggota yang melaksanakan patroli harus mempersiapkan peralatan yang menunjang pelaksanaan patroli (misal : Lampu Senter, Jas Hujan, Sepatu Boot, Tongkat Satpam, Sangkur,&nbsp;Watch Man Clock/Guard Tour/Touch Probe,&nbsp;dll)</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Waktu pelaksanaan patroli&nbsp;area dilaksanakan dengan system acak.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Pelaksanaan patroli harus tercatat (Jam Keberangkatan, jam pulang, hasil penemuan, dsb).</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Patroli area dilaksanakan sesuai dengan arahan Komandan Regu, periksa semua pos, lakukan pemeriksaan kunci &ndash; kunci pintu, jendela, lampu &ndash; lampu, (Kalau dibutuhkan : genset, AC, Boiler, dll) dinding pembatas area perusahaan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Petugas Patroli area yang menemukan suatu kejanggalan atau kecurigaan diwajibkan langsung menghubungi&nbsp; Pos security untuk berkoordinasi dan / atau meminta bantuan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Patroli ke dalam area kantor / area produksi dilaksanakan apabila sudah ada ijin / perintah dari user.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Petugas patroli apabila menemukan karyawan yang melanggar tata tertib perusahaan, agar menegur karyawan ybs dan mencatat identitasnya, lalu melaporkan ke Kepala Bagian / Shift ybs atau melaporkan nya ke HRD dengan melampirkan Berita Acara Kejadian.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Petugas Patroli harus menanyakan kepentingan / keperluan orang &ndash; orang yang tidak dikenal yang berada dalam lingkungan areal patroli / areal kawasan.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-027.pdf', 75630, '2026-08-13 09:20:18', '2026-07-30 11:19:02');
INSERT INTO `materi_buku_saku` (`id_materi`, `id_kategori`, `judul`, `isi`, `icon`, `pdf_path`, `pdf_size`, `pdf_generated_at`, `created_at`) VALUES
(28, 5, 'SOP – TRS 102 : Pengontrolan Kunci-kunci', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: center;\"><span style=\"color: #000000; font-size: 13pt;\"><strong><span style=\"font-family: Arial, sans-serif;\">SOP &ndash; TRS&nbsp;</span></strong><strong><span style=\"font-family: Arial, sans-serif;\">102</span></strong><strong><span style=\"font-family: Arial, sans-serif;\">&nbsp;: Pengontrolan Kunci-kunci</span></strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"color: #000000; font-size: 13pt;\"><strong><span style=\"font-family: Arial, sans-serif;\">Pokok :&nbsp;</span></strong><span style=\"font-family: Arial, sans-serif;\">Penyimpanan semua kunci &ndash; kunci harus terpusat serta terdata, Keluar masuk kunci &ndash; kunci dari tempat penyimpanan harus tercatat dan dilaporkan secara berkala.</span></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"color: #000000; font-size: 13pt;\"><strong><span style=\"font-family: Arial, sans-serif;\">Prosedur :</span></strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"color: #000000; font-size: 13pt;\"><span style=\"font-family: Arial, sans-serif;\">Semua k</span><span style=\"font-family: Arial, sans-serif;\">u</span><span style=\"font-family: Arial, sans-serif;\">nci &ndash; kunci harus tersimpan dalam kotak kunci (Key Box) di Pos Security.</span></span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial, sans-serif; color: #000000; font-size: 13pt;\">Hanya Anggota Security yang berhak untuk mengambil dan menyimpan kunci &ndash; kunci tersebut.</span></li>\n<li style=\"text-align: justify;\"><span style=\"color: #000000; font-size: 13pt;\"><span style=\"font-family: Arial, sans-serif;\">Setelah mempergunakan kunci &ndash; kunci, anggota security harus segera menyimpannya ke Kotak kunci agar tidak terjadi&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">ke</span><span style=\"font-family: Arial, sans-serif;\">lalai</span><span style=\"font-family: Arial, sans-serif;\">an, kunci</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;terbawa &ndash; bawa oleh anggota.</span></span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial, sans-serif; color: #000000; font-size: 13pt;\">Kunci &ndash; kunci yang tersimpan harus terdata.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial, sans-serif; color: #000000; font-size: 13pt;\">Orang yang berhak mempergunakan kunci &ndash; kunci tersebut harus tercatat dan diketahui oleh petugas security.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial, sans-serif; color: #000000; font-size: 13pt;\">Pengambilan dan penyimpanan kunci &ndash; kunci harus sepengetahuan dan ditandatangani oleh Komandan Regu.</span></li>\n<li style=\"text-align: justify;\"><span style=\"color: #000000; font-size: 13pt;\"><span style=\"font-family: Arial, sans-serif;\">Buku laporan (mutasi) keluar</span><span style=\"font-family: Arial, sans-serif;\">/</span><span style=\"font-family: Arial, sans-serif;\">masuk kunci &ndash; kunci harus terpisah peruntukannya.</span></span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial, sans-serif; color: #000000; font-size: 13pt;\">Security harus mengetahui apabila ada penggandaan kunci &ndash; kunci.</span></li>\n<li style=\"text-align: justify;\"><span style=\"color: #000000; font-size: 13pt;\"><span style=\"font-family: Arial, sans-serif;\">Anak kunci yang tidak ada di dalam kotak penyimpanan dan tidak terdata keluar di dalam buku mutasi, harus segera dipertanggungjawabkan keberada</span><span style=\"font-family: Arial, sans-serif;\">a</span><span style=\"font-family: Arial, sans-serif;\">nnya, berada dimana</span><span style=\"font-family: Arial, sans-serif;\">?</span><span style=\"font-family: Arial, sans-serif;\">, oleh siapa</span><span style=\"font-family: Arial, sans-serif;\">?</span><span style=\"font-family: Arial, sans-serif;\">, atas perintah dan/atau ijin siapa</span><span style=\"font-family: Arial, sans-serif;\">?</span><span style=\"font-family: Arial, sans-serif;\">, mengapa</span><span style=\"font-family: Arial, sans-serif;\">?</span><span style=\"font-family: Arial, sans-serif;\">. Semuanya harus tercatat di dalam buku mutasi kunci dan ditandatangani oleh Danru Shift jaga yang bertugas saat kejadian.</span></span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial, sans-serif; color: #000000; font-size: 13pt;\">Apabila anak kunci dinyatakan hilang, maka harus dilakukan penyelidikan dan segera melaporkan ke user untuk pengajuan penggantian kunci / gembok yang anak kuncinya hilang.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial, sans-serif; color: #000000; font-size: 13pt;\">Pelanggaran terhadap prosedur ini akan dikenakan sangsi disiplin yang tegas.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-028.pdf', 75577, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(29, 5, 'SOP – TRS 103 : Karyawan Keluar Pada Jam Kerja', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>103</strong><strong>&nbsp;: Karyawan Keluar Pada Jam Kerja</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Karyawan yang keluar area perusahaan pada saat jam kerja, harus memiliki ijin keluar kantor dan ditandatangni oleh penjabat yang berwenang.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Setiap karyawan yang akan meninggalkan area pada saat jam kerja harus menunjukan surat/form ijin tertulis yang ditandatangani oleh penjabat yang berwenang.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security harus konfirmasi kepada penjabat yang berwenang apabila menemukan kejanggalan / tidak menemukan tanda tangan penjabat yang berwenang pada&nbsp;Surat&nbsp;/ Form ijin meninggalkan tempat kerja.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Anggota Security wajib mendata nama, keperluan, jam keluar/masuk karyawan yang ijin meninggalkan area kerja.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Petugas security tetap wajib melaksanakan body check terhadap karyawan yang meninggalkan area kerja sesuai dengan prosedur yang berlaku.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Karyawan yang meninggalkan area kerja wajib melakukan check clock pada kartu absensinya masing-masing.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Pada saat meninggalkan area kerja, karyawan harus tetap mengenakan ID Card-nya.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Pengecualian untuk peraturan ini adalah dalam kondisi darurat dan atas sepengetahuan / mendapat ijin dari HRD /&nbsp;Kasatpam&nbsp;/ Danru security.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-029.pdf', 75330, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(30, 5, 'SOP – TRS 104 : Keluar Masuk Karyawan', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>1</strong><strong>0</strong><strong>4</strong><strong>&nbsp;: Keluar Masuk Karyawan</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Pengawasan keluar &ndash; masuk karyawan harus dilaksanakan secara ketat untuk menghindari terjadinya pengeluaran asset &ndash; asset perusahaan secara illegal.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Setiap karyawan yang keluar &ndash; masuk wajib melalui pintu akses yang telah ditetapkan oleh perusahaan dan tidak diperkenankan melalui pintu akses yang lainnya.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Karyawan wajib memakai ID Card pada saat memasuki area perusahaan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Security ditugaskan untuk meminta karyawan memakai ID Card pada saat memasuki pintu akses karyawan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Security ditugaskan untuk menahan karyawan yang tidak memakai ID Card untuk tidak memasuki area perusahaan dan konfirmasi kepada penjabat yang berwenang untuk laporan dan meminta petunjuk.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Security wajib mencatat identitas karyawan yang tidak memakai ID Card yang diijinkan oleh penjabat yang berwenang untuk memasuki area perusahaan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Security ditugaskan untuk melakukan Body Check terhadap karyawan yang melewati pintu akses sesuai dengan prosedur Body Check.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Security ditugaskan untuk memeriksa barang bawaan karyawan yang melewati pintu akses sesuai dengan prosedur pemeriksaan barang bawaan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security harus mengetahui dengan pasti jenis-jenis barang yang tidak boleh dibawa masuk / keluar area perusahaan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security diwajibkan melaksanakan prosedur ini dengan sopan dan tegas.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-030.pdf', 75314, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(31, 5, 'SOP – TRS 105 : Pengawasan Absensi', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>1</strong><strong>0</strong><strong>5</strong><strong>&nbsp;: Pengawasan Absensi</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Pelaksanaan Absensi (Amano Card, Fingger Print, Magnetic Card) harus diawasi untuk menegakan tertib administrasi,&nbsp;menghindari penyalahgunaan absensi&nbsp;dan pencegahan terhadap sabotase (Perusakan mesin) yang mungkin terjadi.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Setiap karyawan yang keluar masuk wajib melakukan absensi sesuai dengan system yang berlaku di perusahaan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Absensi wajib dilakukan oleh karyawan yang bersangkutan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security ditugaskan untuk mengingatkan karyawan yang lupa / tidak melaksanakan peng-absen-an.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Security ditugaskan untuk melarang karyawan yang melakukan peng-absen-an bagi karyawan lain (titip absen).</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security dapat mengatur jarum jam / memprogram penunjuk waktu mesin absensi apabila diperlukan dan ditugaskan oleh user.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Pengecualian pelaksanaan prosedur ini berlaku sesuai dengan instruksi dari user / klien.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-031.pdf', 75199, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(32, 5, 'SOP – TRS 106 : Body Check', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>1</strong><strong>0</strong><strong>6</strong><strong>&nbsp;: Body Check</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Body Check dilaksanakan untuk&nbsp;mencegah dan&nbsp;meminimalisasi penguasaan asset &ndash; asset perusahan secara illegal.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security harus mengetahui tujuan dilaksanakannya body check.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security harus mengetahui secara pasti barang &ndash; barang yang tidak boleh dibawa keluar dari area perusahan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Body check dilaksanakan di pintu body check.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Setiap karyawan yang keluar-masuk pintu wajib diperiksa.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Body check dimulai&nbsp; dari sekitar area lengan, samping pinggang, depan dan belakang pinggang menuju ke area paha luar dan paha dalam.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Apabila anggota security menemukan hal &ndash; hal yang mencurigakan, angota berhak untuk meminta karyawan menunjukan barang yang dibawanya.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security dapat menahan karyawan ybs apabila ternyata karyawan ybs tidak bisa menunjukan&nbsp; ijin untuk membawa barang tersebut.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota diwajibkan untuk melaksanakan pemeriksaan dan membuat Berita Acara Pemeriksaan sebagai bahan laporan dan meminta petunjuk kepada user / klien.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Body check harus dilaksanaan secara&nbsp;beretika&nbsp;dan tegas serta mengedepankan prinsip kesopanan.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-032.pdf', 75313, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(33, 5, 'SOP – TRS 107 : Pemeriksaan Barang Bawaan', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>1</strong><strong>0</strong><strong>7</strong><strong>&nbsp;: Pemeriksaan Barang Bawaan</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Pemeriksaan barang bawaan dilaksanakan untuk menyaring dan menahan benda &ndash; benda yang dibawa masuk ke area perusahaan yang dapat mengganggu kinerja karyawan / membahayakan operasional perusahaan.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security harus mengetahui tujuan dilaksanakannya Pemeriksaan Barang Bawaan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security harus mengetahui secara pasti barang &ndash; barang yang tidak boleh dibawa masuk ke area perusahan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Pemeriksaan barang bawaan dilakukan dengan meminta karyawan untuk membuka tas atau barang bawaannya, security melakukan pemeriksaan visual ke dalam tas atau barang bawaan karyawan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security tidak selalu harus melakukan contact fisik (memegang) tas atau barang bawaan karyawan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Apabila anggota security menemukan hal &ndash; hal yang mencurigakan, anggota berhak untuk meminta karyawan mengeluarkan barang dari tas yang dibawanya.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security dapat menahan benda atau barang bawaan karyawan yang dilarang untuk dibawa masuk ke dalam area.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota diwajibkan untuk mengamankan barang bawaan yang disita untuk dikembalikan kepada pemiliknya setelah jam kerja selesai. Dan membuat Berita Acara Pemeriksaan sebagai bahan laporan untuk user / klien.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Pemeriksaan barang bawaan harus dilaksanaan secara sopan dan tegas serta mengedepankan prinsip kesopanan.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-033.pdf', 75391, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(34, 5, 'SOP – TRS 108 : Pemeriksaan Kendaraan Masuk', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>108</strong><strong>&nbsp;: Pemeriksaan Kendaraan Masuk</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Setiap kendaraan yang akan masuk ke dalam area wajib diperiksa untuk mencegah terjadinya hal -hal yang tidak diinginkan</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Kendaraan (truck, mobil, sepeda motor) yang akan masuk diwajibkan antri di depan pos akses masuk dan pintu gerbang harus selalu dalam keadaan tertutup.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota security yang bertugas menghampiri kendaraan tersebut dan mengucapkan salam :&nbsp;</span><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><em>&nbsp;</em><em>&ldquo;Selamat pagi / siang / sore / malam&rdquo;.</em></span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Menanyakan keperluan pengemudi atau orang yang berada di dalam kendaraan untuk memasuki area perusahaan dan dengan mengucapkan : \"</span><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><em>Ada yang bisa saya bantu?&rdquo;</em></span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota memeriksa dokumen yang dibutuhkan.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota konfirmasi ke staff / bagian yang dituju tentang kedatangan kendaraan.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Mengarahkan kendaraan ke tempat yang telah ditentukan.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-034.pdf', 75649, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(35, 5, 'SOP – TRS 109 : Pemeriksaan Kendaraan Keluar', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>109</strong><strong>&nbsp;: Pemeriksaan Kendaraan Keluar</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Setiap kendaraan yang keluar dipastikan membawa dokumen perjalanan yang telah ditentukan oleh perusahaan dan dipastikan tidak membawa barang &ndash; barang milik perusahaan tanpa izin.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota menanyakan dan memeriksa Surat Jalan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Memastikan bahwa Surat Jalan telah diferivikasi (ditandatangani) oleh otoritas yang berwenang.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Apabila menemukan kejanggalan / kurang tandatangan / Cap perusahaan, kendaraan tidak diijinkan keluar dan anggota segera konfirmasi ke manajemen.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Anggota memeriksa bagian dalam (Ruang kaki pengemudi) dan memeriksa bak kendaraan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Apabila menemukan barang yang mencurigakan agar memeriksa dan memastikan bahwa barang tersebut bukan milik perusahaan / sudah mendapat ijin.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-035.pdf', 75100, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(36, 5, 'SOP – TRS 110 : Pemeriksaan Kendaraan Di Object Vital', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>110</strong><strong>&nbsp;: Pemeriksaan Kendaraan Di Object Vital</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Pemeriksaan kendaraan berkaitan dengan potensi ancaman bom dan untuk menerapkan proteksi dini. Pemeriksaan dilakukan secara visual untuk menjaga kenyamanan dan privasi penumpang dan dilakukan dengan sungguh &ndash; sungguh untuk mencari segala bentuk hal &ndash; hal yang tidak lazim / mencurigakan.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\">&nbsp;</p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">1. Anggota meminta ijin untuk melakukan procedure pemeriksaan dengan ramah.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">2. Pemeriksaan Kendaraan dimulai dari sisi kanan kendaraan</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">3. Anggota membuka pintu pengemudi dan melakukan pemeriksaan visual :</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Dashboard depan</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Perhatikan tempat dudukan kemudi , radio tape, dan laci-laci.&nbsp;Apabila semuanya tampak normal dan standar, maka dapat dinyatakan aman / bersih.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Bagian kaki / Bawah kursi</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Perhatikan ruang kosong di bawah kemudi / dashboard, kabin kemudi, kabin penumpang.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Perhatikan ruang kosong antara dek / lantai dengan kursi penumpang dan kemudi di bagian depan dan belakang.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Dashboard belakang (sedan)</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Pemeriksaan pada ruang kosong antara sandaran jok belakang dengan kaca belakang.</span></li>\n</ol>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">4. Membuka pintu penumpang</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">5. Petugas mengamati bagian dalam kendaraan, bila didalam kendaraan ada penumpang, pemeriksa mengambil jarak sekitar 50cm untuk menghindari keberatan dari penumpang. Amati dengan seksama isi serta bentuk bagian dalam kendaraan.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">6. Membuka pintu bagasi, perhatikan hal - hal berikut:</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Lapisan penutup: dinding samping bagasi, penutup ruang ban cadangan.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Kotak peralatan dan benda lainnya.</span></li>\n</ol>\n<p><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">7. Memeriksa denganInspection&nbsp;Mirror:</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Bagian bawah depan.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Bagian bawah mesin.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Bagian bawah belakang.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Memutar ke depan lagi.</span></li>\n</ol>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">8. Khusus :</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Pemeriksaan meliputi perlengkapan yang terletak pada rangka (chasis) dan dek bawah yang tidak terlihat oleh mata.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Perhatikan dengan teliti apakah ada hal yang mencurigakan dan janggal?Misalnya, kabel tambahan atau alat distributor listrik ganda.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Pemeriksaan dengan metal detector hanya dilakukan apabila dalam pemeriksaan visual ditemukan benda ganjil / mencurigakan, mintalah dengan sopan kepada pengemudi/penumpang untuk menjelaskan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Dilarang untuk memeriksa dan membuka sendiri isi bungkusan yang mencurigakan. Mintalah dengan sopan kepada pembawa / pemilik barang untuk membuka sendiri dan menjelaskan kepada petugas.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-036.pdf', 77055, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(37, 5, 'SOP – TRS 111 : Parkir Kendaraan', '<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>111</strong><strong>&nbsp;: Parkir Kendaraan</strong></span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Pokok :&nbsp;</strong>Membantu pengemudi&nbsp;dengan&nbsp;mengarahkan kendaraannya dan menerapkan safety first.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Prosedur :</strong></span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">1. Mempergunakan alat pendukung yang ada kalau diperlukan (Lampu lalin, peluit, rompi lalin, perlengkapan PKD).</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">2. Mengarahkan kendaraan ke slot parkir yang telah ditentukan agar tidak semrawut</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">3. Mengarahkan kendaraan dengan posisi yang memudahkan untuk keluar.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">4. Posisi Anggota di arah belakang, anggota berada di sisi kanan kendaraan agar terlihat dari kaca spion.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">5. Mengarahkan dengan gerakan tangan dan dengan instruksi suara yang terdengar oleh pengemudi atau mempergunakan peluit.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">5. Arahan untuk pengemudi harus jelas.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">7. Untuk menghindari klaim sepihak,&nbsp;setelah kendaraan terparkir&nbsp;maka dilakukan pemeriksaan secara visual dan singkat :</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Kondisi fisik kendaraan (Cat body, bumper, ban)</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Kunci pintu.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Jendela mobil.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Barang &ndash; barang di dalam kendaraan.</span></li>\n</ol>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">8. Mengingatkan pengemudi apabila ditemukan pintu tdk terkunci, jendela yang terbuka atau ada barang berharga yang ditinggalkan di dalam kendaraan.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">9. Meminta pengemudi untuk mempergunakan / tidak, rem tangan / posisi gear sesuai dengan keadaan.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">10. Memberikan kartu parkir.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">11. Kendaraan keluar :</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Mengambil kartu parkir.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Melakukan pemeriksaan STNK apabila diharuskan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Menerapkan aturan Pengaturan Lalulintas standar Polri.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Posisi Anggota menempati posisi yang paling strategis / maksimal untuk mengatur lalin.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Menerapkan aturan safety first.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Secara umum anggota dilarang menerima uang tip.</span></li>\n</ol>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">12. Administrasi perparkiran :</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Mencatat jenis dan Nopol kendaraan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt;\">Mencatat jam keluar &ndash; masuk kendaraan.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-037.pdf', 76604, '2026-08-13 09:20:18', '2026-07-30 11:19:02');
INSERT INTO `materi_buku_saku` (`id_materi`, `id_kategori`, `judul`, `isi`, `icon`, `pdf_path`, `pdf_size`, `pdf_generated_at`, `created_at`) VALUES
(38, 5, 'SOP – TRS 112 : Pengawasan Loading – Unloading\n\n', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>112</strong><strong>&nbsp;: Pengawasan Loading &ndash; Unloading</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Memastikan barang yang loading &ndash; unloading sesuai dengan surat jalan dan membantu perusahaan dalam memenuhi standar (Buyer) untuk ekspor.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">1. Mengarahkan kendaraan ke tempat penimbangan sebelum dan sesudah proses loading - unloading.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">2. Mencatat hasil penimbangan kendaraan.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">3. Area loading &ndash; unloading harus steril dari orang &ndash; orang yang tidak berkepentingan termasuk sopir dan kenek.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">4. Nama dan photo petugas Loading &ndash; unloading harus tertera di area loading &ndash; unloading.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">5. Anggota harus memastikan pelaksana loading &ndash; unloading adalah petugas yang telah ditunjuk oleh manajemen dan memakai ID card.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">6. Petugas memeriksa kelengkapan administrasi / surat &ndash; surat.</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Jenis.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Jumlah.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Tanda tangan / Cap perusahaan.</span></li>\n</ol>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">7. Petugas memeriksa segel dan kunci (Gembok) box kendaraan.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">8. Mendokumentasikan (Mem-photo) segel dan kunci box kendaraan apabila diperlukan.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">9. Mengawasi proses loading &ndash; unloading.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">10. Melakukan penghitungan jumlah dan jenis barang yang loading &ndash; unloading apabila diperlukan.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">11. Mengawasi pelaksanaan buka -&nbsp; kunci gembok dan segel.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-038.pdf', 75409, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(39, 5, 'SOP – TRS 113 : Pengawasan Ruang Locker Karyawan', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>113</strong><strong>&nbsp;: Pengawasan Ruang Locker Karyawan</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Memastikan keamanan barang &ndash; barang yang disimpan di locker dan memastikan karyawan&nbsp;untuk&nbsp;menyimpan barang &ndash; barang yang dilarang&nbsp;dibawa masuk&nbsp;ke ruang produksi ( tempat kerja) di locker.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Memastikan sign/tanda&nbsp;himbauan untuk tidak membawa barang &ndash; barang berharga ditempel di tempat yang mudah dilihat karyawan.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Memastikan pintu locker terkunci pada jam &ndash; jam setelah karyawan masuk dan setelah karyawan istirahat.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Mengamankan anak kunci locker yang tergantung / tertinggal.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Menginformasikan pintu locker yang tidak terkunci kepada karyawan yang bersangkutan apabila ditemukan locker tidak terkunci.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Mengawasi orang &ndash; orang yang memasuki area locker room.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Melarang orang yang tidak berkepentingan di luar jam istirahat, masuk / pulang berada di area locker room.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-039.pdf', 75140, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(40, 5, 'SOP – TRS 114 : Pintu Gerbang', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>114</strong><strong>&nbsp;: Pintu Gerbang</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Area Pabrik / Industri, adalah area tertutup (Restricted Area).</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Memastikan pintu gerbang selalu dalam keadaan tertutup dan terkunci.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Memastikan orang / kendaraan yang akan masuk sudah dikenali sebelum membuka pintu gerbang.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Memastikan slot sudah terkunci ketika mengarahkan kendaraan memasuki / keluar pintu gerbang.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Memastikan kendaraan yang akan masuk bisa memasuki gerbang tanpa masalah / mampu mengukur / memperkirakan ukuran kendaraan bisa melewati pintu gerbang (tinggi dan lebar nya)</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Segera menutup pintu gerbang ketika kendaraan telah memasuki / keluar area dan segera mengunci kembali.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-040.pdf', 74959, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(41, 5, 'SOP – TRS 115 : Pengawalan', '<p style=\"text-align: justify;\"><span style=\"color: #000000; font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>115</strong><strong>&nbsp;: Pengawalan</strong></span></p>\n<p style=\"text-align: justify;\"><span style=\"color: #000000; font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Pokok :&nbsp;</strong>Pengamanan dilaksanakan dengan standar yang ada berdasarkan penilaian nilai (value) objek pengawalan dan resiko pengawalan.</span></p>\n<p style=\"text-align: justify;\"><span style=\"color: #000000; font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Prosedur :</strong></span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">1. Pengawalan dilaksanakan atas sepengetahuan Chief Security atau Danru setelah ada permintaan pengawalan dari klien yang mengisi Escorting Request Form (ER Form).</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">2. Pelajari ER Form dengan teliti, kemudian lakukan persiapan pengawalan sesuai kebutuhan berupa pemilihan personil sesuai dengan kualifikasi, kendaraan, senjata, alat komunikasi, body protector, dll.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">3. Kualifikasi dasar personil untuk melakukan pengawalan adalah sbb:</span></p>\n<ol style=\"list-style-type: lower-alpha;\">\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">Skill beladiri (tangan kososng dan alat).</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">Skill penggunaan alat komunikasi.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">Skill mengemudikan R4 dan R2 untuk antisipasi apabila ada keadaan darurat.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Menguasai rute perjalanan.</span></li>\n</ol>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">4. Pelajari rute perjalananan dengan teliti, apakah ada titik &ndash; titik kemacetan, dimana Pos Polisi terdekat.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">5. Usulkan alternatif &ndash; alternatif perjalanan yang paling aman.</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">6. Semua kronologis pengawalan dicatat dalam Buku Laporan Pengawalan (Escorting Report)</span></p>\n<p style=\"text-align: justify;\"><span style=\"font-family: arial, helvetica, sans-serif; color: #000000; font-size: 13pt;\">7. Pengawalan dilakukan dengan prinsip kehati-hatian dan kecurigaan / kewaspadaan.</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-041.pdf', 75405, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(42, 5, 'SOP – TRS 116 : Penggunaan Radio Komunikasi', '<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>SOP &ndash; TRS&nbsp;</strong><strong>116</strong><strong>&nbsp;: Penggunaan Radio Komunikasi</strong></span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Pokok :&nbsp;</strong>Radio komunikasi merupakan sarana pelaporan dari&nbsp;pos jaga&nbsp;ke&nbsp;Pos Utama, penyebaran informasi dari&nbsp;Pos Utama&nbsp;ke seluruh&nbsp;pos jaga, sarana untuk meminta bantuan dalam keadaan&nbsp;darurat&nbsp;dan alat penunjang operasional security dalam satu area.</span></p>\n<p style=\"color: #666666; font-family: \'Trebuchet MS\', Trebuchet, Verdana, sans-serif; font-size: 13.2px; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; background-color: #ffffff; text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\"><strong>Prosedur :</strong></span></p>\n<ol>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Radio komunikasi tidak boleh digunakan untuk komunikasi pribadi (ngobrol, bercanda, dll)</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Radio komunikasi di pos harus selalu dalam keadaan stand by.</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Pelaporan dari area&nbsp;jaga&nbsp;harus dilaksanakan minimal&nbsp;1&nbsp;jam sekali.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Dilarang melakukan jamming (mengganggu frekuensi) dengan memasukan suara &ndash; suara lain, atau dengan menekan tombol PTT tanpa keperluan operasional.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Sebelum melakukan panggilan (berbicara) tekan tombol PTT selama 2 detik, baru berbicara.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Rawatlah HT seperti anda merawat HT milik sendiri</span></li>\n<li><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif; color: #000000;\">Dilarang untuk mengkotak-katik pesawat HT baik sengaja maupun tidak sengaja, apabila terjadi kerusakan pesawat segera laporkan ke&nbsp;Pos Utama.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Ketika pesawat sedang di charge, harus dalam keadaan mati (off). Menggunakan HT dalam keadaan di charge dapat menyebabkan kerusakan pesawat.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">HT harus dibawa dengan menggunakan antena pendek ketika sedang melaksanakan patroli dengan cara digantung di samping badan.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Apabila jaringan sedang digunakan, yang lain harus sabar menunggu, dan apabila ada taruna yang mendesak, harus menggunakan kata &ldquo;Intrap&rdquo;.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Gunakanlah etika berkomunikasi yang baik.</span></li>\n<li><span style=\"font-family: arial, helvetica, sans-serif; font-size: 13pt; color: #000000;\">Seluruh pelanggaran dari petunjuk teknis protap penggunaan radio komunikasi ini akan dikenakan sangsi.</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/05-sop-satpam/materi-042.pdf', 76122, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(43, 6, 'Sandi Angka ', '<p style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Sandi Angka&nbsp;</strong></span></p>\n<p><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">1-1 hubungi lewat telepon</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">1-2 menghadap pusat/posko</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">1-4 hubungi lewat HT</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-4 testing radio</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-1 komunikasi kurang jelas</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-2 komunikasi jelas/baik</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">3-3 kualitas suara jelek</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">4-4 kualitas suara baik</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">5-5 kualitas suara baik sekali</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">6-1 terjadi perampokan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">6-2 terjadi pencurian</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">6-3 trjadi penganiayaan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">6-5 terjadi kebakaran</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">6-7 terjadi demonstrasi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-6 mengerti</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-7 berita disampaikan kepada&hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-1-0 Tidak mengudara/mati</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-1-1 mengudara/ standby</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-1-2 diulangi/kurang jelas</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-1-3 selamat bertugas</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-1-5 keadaan cuaca</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">8-1-6 waktu/jam</span><br /><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-1 Sulit didengar // Penerimaan buruk</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-2 Didengar jelas // Penerimaan baik</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-3 Berhenti mengudara / memancar</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-4 Benar // Dimengerti</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-5 Ada pesan untuk disampaikan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-6 Sedang sibuk kecuali ada berita penting</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-7 Mengalami kerusakan // Tidak dapat mengudara</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-8 Tidak ada kerusakan // Dapat mengudara</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-9 Mohon diulangi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-10 Penyampaian berita selesai</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-11 Berbicara terlalu cepat</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-12 Mengundurkan diri karena ada tamu</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-13 Laporan keadaan cuaca / jalanan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-14 Informasi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-15 Informasi sudah disampaikan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-16 Mohon dijemput / diambil di &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-17 Ada urusan penting</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-18 Sesuatu untuk kita</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-19 Bukan untuk Anda, harap kembali</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-20 Lokasi // Posisi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-21 Kontak / hubungan melalui telepon</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-22 Melapor langsung ke &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-23 Menunggu // Stand by</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-24 Selesai melaksanakan tugas</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-25 Dapatkah menghubungi / kontak dengan &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-26 Pesanan terakhir kurang diperhatikan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-27 Pindah ke jalur / channel &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-28 Nama panggilan // Callsign</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-29 Waktu hubungan / kontak habis</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-30 Tidak menaati peraturan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-31 Antena yang digunakan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-32 Laporan sinyal dan modulasi // Radio check</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-33 KEADAAN DARURAT // EMERGENCY</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-34 Butuh bantuan, ada kesulitan di stasiun ini</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-35 INFORMASI RAHASIA</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-36 Jam berapa waktu yang tepat ?</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-37 PERLU MOBIL DEREK DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-38 PERLU AMBULANS DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-39 Pesan sudah disampaikan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-40 PERLU DOKTER</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-41 Mohon pindah ke jalur / channel &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-42 ADA KECELAKAAN DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-43 Kemacetan lalu lintas di &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-44 Ada pesan untuk Anda</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-45 Dalam jangkauan mohon melapor</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-46 Memerlukan montir</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-50 Mohon kosongkan jalur / channel</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-60 Apakah ada pesan selanjutnya ?</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-62 Tidak dimengerti, melalui telepon saja</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-63 Tugas / pekerjaan dilanjutkan di &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-64 Pekerjaan telah selesai / bersih</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-65 Menunggu berita lanjutan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-67 Semua unit setuju</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-69 Pesanan telah diterima</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-70 KEBAKARAN DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-71 Pesawat KRAP (RIG) yang dipakai</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-73 Kurangi kecepatan di &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-74 Tidak // Negatif</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-75 Penyebab gangguan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-76 Dalam perjalanan ke &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-77 Belum / tidak menghubungi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-81 Pesankan kamar di hotel &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-82 Pesankan kamar untuk &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-84 Nomor telepon</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-85 Alamat</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-89 Butuh montir radio</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-90 Gangguan pesawat televisi (TVI)</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-91 Bicara dekat mikropon</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-92 Pemancar perlu penyesuaian</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-93 Apakah frekuensi sudah tepat ?</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-94 Berbicara agak panjang</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-95 Mengudara dengan sinyal setiap 5 detik</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-97 Tes pada pemancar</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-99 Tugas selesai, semua orang selamat</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-100 Akan ke kamar mandi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-200 BUTUH BANTUAN POLISI DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-300 BUTUH PEMADAM KEBAKARAN DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-400 BUTUH PETUGAS KETERTIBAN UMUM DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-500 BUTUH BANTUAN PROVOST DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-600 BUTUH BANTUAN GARNIZUN DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-700 BUTUH BANTUAN S.A.R. DI &hellip;</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">10-800 BUTUH BANTUAN PERUSAHAAN LISTRIK DI &hellip;</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/06-sandi-komunikasi/materi-043.pdf', 80066, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(44, 6, 'Sandi Huruf ', '<p style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>Sandi Huruf&nbsp;</strong></span></p>\n<p><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Taruna : Berita</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Gelombang : Jam/waktu</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Semut : Pelajar</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Lalat : Mahasiswa</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pangkalan : Rumah/kediaman</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Cangkulan : Kantor/tempat kerja</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Gajah : Derek</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Komando : Kantor polisi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Tikar : Surat</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Buntut tikus : Antena pendek (HT)</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Belalai gajah : Antena atas</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Laka : Kecelakaan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Jaya 65 : Kebakaran</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Timor Kupang Pati : Tempat Kejadian Perkara</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Timor Lombok Pati : Telepon</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Timor Kupang Ambon : TerKendali</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Aman</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Halong Timur : Handy Talky (HT)</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Halong Pati : Hand Phone (HP)</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kupang Rembang : KendaRaan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kupang Ambon : Kereta Api</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Wilis Kendal : Walikota</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kendal Cepu : KeCamatan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kendal Lombok : KeLurahan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rembang Wilis : RW</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rembang Timur : RT</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rembang Rembang : Serse</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rembang Solo : Rumah Sakit</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Rembang Pati : Rupiah</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Anak Kijang : Pencuri/Tersangka</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ambon Pati : Anggota Polri</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ambon Demak : Angkatan Darat</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ambon Lombok : Angkatan Laut</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Ambon Ungaran : Angkatan Udara</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pati Medan : Polisi Militer</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Timor Medan : Tamu/Teman</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Kresna : Presiden</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bima : Wakil Presiden</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Timor Bandung I : Kapolri</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Metro I : Kapolda</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Timor I : Kapolres</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Lombok-Lombok : Lalu Lintas</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Timor Lombok : Lampu Lalu Lintas/Traffic Light</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Opak Pati Solo : Derek</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Lombok Pati : Kantor Polisi</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Lombok Irian : Surat</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Lombok Demak : Antena Pendek (HT)</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bandung-Bandung : Barang Bukti (BB)</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bandung2 Padat : Makan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Bandung2 Medan : Bahan Bakar Minyak</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Lampiran/Ambon : Istri</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Monik : Anak</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Solo Bandung : Stand By</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Solo Garut : SiaGa</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Medan Demak : Meninggal Dunia</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Pati Ambon Medan : Pengamanan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Aambon Pati-Pati : Apel</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Palang Hitam : Mobil Jenazah</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Demak Pati Kendal : Dinas Pemadam Kebakaran</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/06-sandi-komunikasi/materi-044.pdf', 76910, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(45, 6, 'SANDI ALPHABET LOKAL/INDONESIA', '<p style=\"text-align: center;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\"><strong>SANDI ALPHABET LOKAL/INDONESIA</strong></span></p>\n<p style=\"text-align: justify;\"><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">A=Ambon</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">B=Bandung</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">C=Cepu</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">D=Demak</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">F=Flores</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">G=Garut</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">H=Halong</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">I=Irian</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">J=Jepara</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">K=Kendal</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">L=Lombok</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">M=Medan</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">N=Namlea</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">O=Opak</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">P=Pati</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Q=Quibek</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">R=Rembang</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">S=Solo</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">T=Timor</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">U=Ungaran</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">V=Viktor</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">W=Wilis</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">X=Ekstra</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Y=Yongki</span><br /><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Z=Zainal</span></p>', 'icon1', 'uploads/buku_saku/materi_pdf/06-sandi-komunikasi/materi-045.pdf', 74851, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(46, 6, 'SANDI ALPHABET INTERNASIONAL', '<p style=\"text-align: center;\"><strong>SANDI ALPHABET INTERNASIONAL</strong></p>\n<p style=\"text-align: justify;\"><br />A=Alpha<br />B=Bravo<br />C=Charlie<br />D=Delta<br />E=Echo<br />F=Foxtrot<br />G=Golf<br />H=Hotel<br />I=India<br />J=Juliett<br />K=Kilo<br />L=Lima<br />M=Mike<br />N=November<br />O=Oscar<br />P=Papa<br />Q=Quebec<br />R=Romeo<br />S=Sierra<br />T=Tango<br />U=Uniform<br />V=Victor<br />W=Whiskey<br />X=X-Ray<br />Y=Yankee<br />Z=Zulu</p>', 'icon1', 'uploads/buku_saku/materi_pdf/06-sandi-komunikasi/materi-046.pdf', 74871, '2026-08-13 09:20:18', '2026-07-30 11:19:02'),
(47, 7, 'Referensi', '<ol>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Peraturan Kepala Kepolisian Negara Republik Indonesia Nomor 24 Tahun 2007 Tentang Sistem Manajemen Pengamanan Organisasi, Perusahaan dan/atau Instansi/Lembaga Pemerintah.</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Alex S. Nitisemito; Manajemen Personalia; 1984: 199</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">T.Hani Handoko; Manajemen; 1994:208</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">http://www.satpampekanbaru.com/2017/01/kode-sandi-komunikasi-satpam.html</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Gouzali Saydam; Manajemen Sumber Daya Manusia; 1996:202</span></li>\n<li style=\"text-align: justify;\"><span style=\"font-size: 13pt; font-family: arial, helvetica, sans-serif;\">Sumber &ndash; sumber lain dari internet</span></li>\n</ol>', 'icon1', 'uploads/buku_saku/materi_pdf/07-referensi/materi-047.pdf', 74114, '2026-08-13 09:20:18', '2026-07-30 11:19:02');

